import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    if len(data) < 2:
        values = []
    else:
        values = list(map(int, data[1].split()))
    # Filter out null nodes represented by -1
    result = [str(x) for x in values if x != -1]
    # Output space-separated nodes
    print(' '.join(result))

if __name__ == "__main__":
    main()
